INSERT INTO public.careers (slug, name, area, is_gold_set, status, family_id, fields, curriculum, universities, duration, employability, salary)
SELECT 
    'ingenieria-de-minas', 
    'Ingeniería de Minas', 
    'Ingeniería', 
    false, 
    'active', 
    id, 
    ARRAY[]::text[], 
    ARRAY[]::text[], 
    ARRAY[]::text[], 
    '5 años', 
    'Alta', 
    'S/ 3,500 — S/ 8,000'
FROM public.career_families WHERE name = 'Carreras tradicionales'
ON CONFLICT (slug) DO UPDATE SET
    name = EXCLUDED.name,
    area = COALESCE(public.careers.area, EXCLUDED.area),
    is_gold_set = EXCLUDED.is_gold_set,
    family_id = EXCLUDED.family_id,
    updated_at = now();
